def P(num,h,fig,tier,grant,inv,title,teaches,figs,status="Expired",**k):
    d=dict(num=num,hash=h,fig=fig,tier=tier,grant=grant,inv=inv,title=title,teaches=teaches,figs=figs,status=status); d.update(k); return d
INTRO = "<p>These are the patent drawings behind this guide's binders, bricks and blocks. They cover lime kilns you can build from stone, a brick machine worked by hand or horse, Palmer's hollow concrete block and the molding machines for it, a wheelbarrow mixer, and the first U.S. patents for steel-reinforced concrete. All are long expired and free to copy. Read them with Parts 3, 4 and 6 of this guide, and follow the red hazard boxes: quicklime and wet cement burn skin and eyes.</p>"
UNPATENTED = ["Burning lime in a pit or clamp, mud-brick and adobe moulding, rammed earth and lime mortar are ancient practices that anyone may use."]
PATENTS = [
P("US7757","ab/65/92/d70ce4f9b1b0bb/US7757.pdf","23/f0/d3/b869b0f293fc66/US7757-drawings-page-1.png","A","1850-11-05","William McCoy (Fannettsburg, Pennsylvania)","Lime-kiln",
  "A stone farm lime kiln changed to burn coal instead of large amounts of wood. McCoy says the wood fuel cost nearly as much as the lime sold for. The section shows the shaft, the fire arches and the draw-hole: the same layout as the simple kiln in section 3.2.","Vertical section and plan of the kiln"),
P("US18531","d3/6c/74/cd54ea8a86e2ae/US18531.pdf","8f/58/e1/61667de662df3a/US18531-drawings-page-1.png","A","1857-11-03","A. G. Anderson (Quincy, Illinois)","Lime-kiln",
  "An improved continuous or &ldquo;perpetual draw&rdquo; lime kiln: stone is fed at the top and burnt lime is drawn at the bottom without letting the fire go out. The two sections at right angles show how the stack, fireplaces and draw openings are laid out.","Figs. 1&ndash;2 central vertical sections at right angles"),
P("US384541","01/aa/20/2705e4f6655497/US384541.pdf","98/90/50/efa3d8ad699f45/US384541-drawings-page-1.png","A","1888-06-12","Harmon S. Palmer (Chattanooga, Tennessee)","Building-block",
  "Palmer's early interlocking building block, shown as a wall going up (Fig. 1) and as a single block (Fig. 2). It is a pattern for shaping hand-moulded blocks so the courses lock together.","Fig. 1 wall in course of erection; Fig. 2 single block"),
P("US8269","05/90/df/67817bcade4ee9/US8269.pdf","f2/e2/ad/0b8f691dabeffb/US8269-drawings-page-1.png","B","1851-08-05","Luther Brown (Canandaigua, New York)","Brick-machine",
  "A portable brick machine to be worked by hand or horse power, needing few hands. Clay is tempered and pressed into moulds. It shows the pug-mill-and-mould-table layout for making bricks at more than hand speed.","Fig. 1 section; Fig. 2 plan"),
P("US623686","5e/a9/73/6ece58daf3108c/US623686.pdf","d9/8a/56/7ec891721a8923/US623686-drawings-page-1.png","B","1899-04-25","Harmon S. Palmer (Chicago, Illinois)","Machine for molding hollow concrete building-blocks",
  "A cast-iron machine for moulding hollow concrete blocks. It has a base plate, a mould with hinged sides, and core blocks raised and lowered by a crosshead and links, so a block can be rammed and taken out at once. The layout can be copied in wood and steel for section 4.10.","Sheet 1: elevation of mould, cores and lever linkage"),
P("US727427","f2/1f/7b/b9a4d8b2b3f74d/US727427.pdf","6f/80/1c/6a1de91e2c8448/US727427-drawings-page-1.png","B","1903-05-05","Harmon S. Palmer (Washington, D.C.)","Machine for molding hollow concrete building-blocks",
  "Palmer's later adjustable block machine. It can be set to make corner blocks, blocks with angled faces for bay windows, and half, quarter and other part-blocks of different lengths and widths.","Sheet 1: general view of the machine"),
P("US711524","bb/98/01/f0f42008a26ac8/US711524.pdf","a8/dd/b2/161cbfda8ca4cc/US711524-drawings-page-1.png","A","1902-10-21","Hugh J. Phillips & Michael F. Guiney (Washington, D.C.)","Concrete-mixer",
  "A portable concrete mixer built as a wheelbarrow, a wheeled receptacle pushed by hand. Cement, sand, stone and water are mixed as the barrow is wheeled to the job, so the mixing happens on the way to the forms.","Sheet 1: the barrow-mixer and its internal mixing parts"),
P("US305226","85/93/83/9903d53b2b0797/US305226.pdf","16/a5/d7/ad798f4286a908/US305226-drawings-page-1.png","C","1884-09-16","Ernest L. Ransome (San Francisco, California)","Building construction (twisted reinforcing bar)",
  "Before this, straight iron rods with nuts and washers on the ends were used, but under load they stretched and let the concrete crack. Ransome twisted the rods or strips so they are fixed in the concrete &ldquo;at every point from end to end&rdquo;, forming a rigid bond along the whole length.","Fig. 1 structure partly in section with rods; Fig. 2 the spiral (twisted) rod"),
P("US206112","b0/c2/c6/bd54eae1ca15b5/US206112.pdf","f1/36/fb/aeffb708c4ae77/US206112-drawings-page-6.png","C","1878-07-16","Thaddeus Hyatt (New York, New York)","Improvement in composition floors, roofs, pavements, &c.",
  "Hyatt's broad patent on hydraulic cement and concrete combined with iron as a building material for floors, roofs and pavements. The patent refers to his book of experiments with Portland-cement concrete combined with iron. The sheets show iron set into slabs and beams.","Drawing sheets: reinforced slabs, beams and floor sections"),
P("US644057","75/6f/ee/7098b65ac048fd/US644057.pdf","0f/a2/d0/8babbb1f23bc7f/US644057-drawings-page-1.png","C","1900-02-27","Charles L. Carman (Gates Iron Works)","Rotary kiln",
  "A rotary kiln: a long tube that is turned while heat is applied, for roasting (calcining) portland cement or similar materials. This patent adds discharge openings that open and close as the tube turns, letting the calcined material out while keeping large amounts of cold air from getting in. It shows how factory portland cement was made, which is out of reach for a workshop; compare 3.5 Hydraulic lime, natural cement, portland.","Fig. 1 the kiln, partly in section; Figs. 2-4 the discharge mechanism"),
]
